工程防线，守住不可预测的模型输出。","script_hash":"e645b65b759bdaa60b2135b1f965939c250f36052d4c6224d29efb390904438e","source_size_bytes":12342818,"task_acceptance_hash":"f61f700abec2508659d2ab59a7dff5afb016e2e4410210647ca824b2b6990e07","task_id":"f5fbbc786b1b4835a8ba471fd7378b8d","task_input_hash":"6e6e4e29a04878b54c81e9ffc15d827641873ee2b89b11b7b940605bcaec5bd3","task_plan_hash":"2f2587f90866c88868ca68f112eef1eaecf1d1be319334ab947c2ea62233f39a","task_request_hash":"0e2ee11d3ec42e55be541dab12e90a0c57e3b5756c7c1f5ebaafbe8b66172044","task_result_signature_hash":"08df7af27179ba00d7aaba9218bf43fb27670defb059f8dd103891ff3646c5d1","tts_source_hash":"1847924c72f226969b76450ff2902ebf85864c4b8c3ef30b3b12ffc7cdd421d4","unit_id":44,"workflow":{"checksum":"5d3937554338a7325449c7b36c6dbb4b0d26e7367c0904e911026875d4549dee","id":33,"version":1}},"tts":{"accepted_hash":"52f593b32369294afac13615953dd1101b0c9c71364a63577805c287470f512b","asset_refs":[{"content_hash":"52f593b32369294afac13615953dd1101b0c9c71364a63577805c287470f512b","material_revision_id":80}],"attempt_id":133,"context_hash":null,"decision":"accepted","domain":"media","entity_id":80,"feedback_event_id":293,"node_id":"tts","output_kind":"material_revision","payload":{"content_hash":"52f593b32369294afac13615953dd1101b0c9c71364a63577805c287470f512b","material_revision_id":80,"mime_type":"audio/wav"},"payload_hash":"52f593b32369294afac13615953dd1101b0c9c71364a63577805c287470f512b","project_output_id":44,"revision_no":1}}
